const roleSetSession=setSession;setSession=function(account,remember=true){roleSetSession(account,remember);const full=accounts.find(a=>a.id===account.id)||account;if(full.homeCoords)map.setView(full.homeCoords,15);if(account.role==='owner'){const mine=places.find(p=>p.ownerId===account.id);if(mine)map.setView([mine.lat,mine.lng],16)}render()};
