$('#importOsmPlaces').onclick=async()=>{const button=$('#importOsmPlaces'),c=map.getCenter();button.disabled=true;button.textContent='불러오는 중…';try{const query=`[out:json][timeout:20];(nwr["amenity"~"^(cafe|restaurant)$"](around:2500,${c.lat},${c.lng}););out center tags 60;`,response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:query}),data=await response.json();let added=0;for(const item of data.elements||[]){const t=item.tags||{},lat=item.lat||item.center?.lat,lng=item.lon||item.center?.lon,id=`osm-${item.type}-${item.id}`;if(!t.name||!lat||!lng||places.some(p=>p.id===id))continue;places.push({id,name:t.name,type:t.amenity==='restaurant'?'food':'cafe',area:[t['addr:city'],t['addr:street'],t['addr:housenumber']].filter(Boolean).join(' ')||'주소 정보 보완 필요',lat,lng,image:'',ownerGallery:[],visitorGallery:[],desc:'OpenStreetMap에서 불러온 장소 · 상세 정보 확인 필요',hours:t.opening_hours||'영업시간 정보 없음',menus:[],reviews:[],quietTimes:[],featureVotes:{},featureVoters:{},reservable:false,source:'OpenStreetMap'});added++}store.set('places',places);populatePlaces();render();toast(`${added}곳을 불러왔어요. 중복 장소는 제외했습니다.`)}catch(error){toast('주변 가게를 불러오지 못했어요. 잠시 후 다시 시도해주세요.')}finally{button.disabled=false;button.textContent='⌁ 주변 가게'}};
let repairedLegacyLocation=false;places.forEach(p=>{if(/황어로\s*188/.test(p.area||'')&&(p.lat<37.50||p.lat>37.70||p.lng<126.60||p.lng>126.85)){p.lat=37.5785;p.lng=126.7315;p.resolvedAddress='인천 계양구 황어로 188 인근 · 지도에서 정확한 건물 위치를 확인해주세요.';repairedLegacyLocation=true}});if(repairedLegacyLocation)store.set('places',places);
