let routeStartPoint=null,routeEndPoint=null,clickedMapPoint=null;
if(!$('#mapClickActions'))document.body.insertAdjacentHTML('beforeend',`<section id="mapClickActions" aria-live="polite"><button id="closeMapActions" aria-label="닫기">×</button><b id="clickedMapAddress">선택한 위치</b><small id="clickedMapCoords"></small><div><button data-map-action="cafe">☕ 카페 등록</button><button data-map-action="food">🍽 식당 등록</button><button data-map-action="start">● 출발지</button><button data-map-action="end">◆ 도착지</button></div></section><section id="routePointBar"><span id="routeStartLabel">출발지 미선택</span><b>→</b><span id="routeEndLabel">도착지 미선택</span><button id="showPointRoute">경로 보기</button><button id="clearPointRoute">초기화</button></section>`);
function reverseNaverPoint(lat,lng){return new Promise(resolve=>{if(!naver.maps.Service)return resolve('지도에서 선택한 위치');naver.maps.Service.reverseGeocode({coords:new naver.maps.LatLng(lat,lng),orders:'roadaddr,addr'},(status,response)=>{if(status!==naver.maps.Service.Status.OK)return resolve('지도에서 선택한 위치');const r=response.v2?.results?.[0],region=r?.region,land=r?.land;resolve([region?.area1?.name,region?.area2?.name,region?.area3?.name,land?.name,land?.number1,land?.number2].filter(Boolean).join(' ')||'지도에서 선택한 위치')})})}
async function findNearbyPublicPlace(point){try{const q=`[out:json][timeout:8];nwr["amenity"~"^(cafe|restaurant)$"](around:45,${point.lat},${point.lng});out center tags 8;`,res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:q}),data=await res.json(),candidates=(data.elements||[]).map(x=>({raw:x,lat:x.lat||x.center?.lat,lng:x.lon||x.center?.lon})).filter(x=>x.raw.tags?.name&&x.lat&&x.lng).map(x=>({...x,d:map.distance(point,x)})).sort((a,b)=>a.d-b.d);return candidates[0]||null}catch{return null}}
map.on('click',async e=>{const point={lat:e.latlng.lat,lng:e.latlng.lng},near=places.map(p=>({p,d:map.distance(point,p)})).filter(x=>x.p.type==='cafe'||x.p.type==='food').sort((a,b)=>a.d-b.d)[0];if(near&&near.d<=90){$('#mapClickActions').classList.remove('show');openDetail(near.p.id);return}const requestPoint=clickedMapPoint={...point,address:'주소·가게 정보 확인 중…'};$('#clickedMapCoords').textContent=`${point.lat.toFixed(6)}, ${point.lng.toFixed(6)}`;$('#clickedMapAddress').textContent=requestPoint.address;$('#mapClickActions').classList.add('show');const [address,publicPlace]=await Promise.all([reverseNaverPoint(point.lat,point.lng),findNearbyPublicPlace(point)]);if(clickedMapPoint!==requestPoint)return;requestPoint.address=address;if(publicPlace&&publicPlace.d<=45&&$('#mapClickActions').classList.contains('show')){const t=publicPlace.raw.tags,id=`osm-${publicPlace.raw.type}-${publicPlace.raw.id}`;let p=places.find(x=>x.id===id);if(!p){p={id,name:t.name,type:t.amenity==='restaurant'?'food':'cafe',area:address,lat:publicPlace.lat,lng:publicPlace.lng,image:'',ownerGallery:[],visitorGallery:[],desc:'공개 지도 데이터에서 찾은 장소 · 정보 수정 가능',hours:t.opening_hours||'영업시간 정보 없음',menus:[],reviews:[],quietTimes:[],featureVotes:{},featureVoters:{},reservable:false,source:'OpenStreetMap'};places.push(p);store.set('places',places);populatePlaces();render()}$('#mapClickActions').classList.remove('show');openDetail(p.id);return}$('#clickedMapAddress').textContent=address});
$('#closeMapActions').onclick=()=>$('#mapClickActions').classList.remove('show');
function registerFromMap(type){if(!session)return toast('로그인 후 지도 장소를 등록할 수 있어요.');const f=$('#newPlaceForm');f.elements.type.value=type;f.elements.area.value=clickedMapPoint.address;f.dataset.pickedLat=clickedMapPoint.lat;f.dataset.pickedLng=clickedMapPoint.lng;f.dataset.addressLabel=clickedMapPoint.address;$('#newPlaceLocationHelp').textContent=`지도에서 선택: ${clickedMapPoint.address}`;$('#mapClickActions').classList.remove('show');$('#newPlaceDialog').showModal();f.elements.name.focus();toast(type==='cafe'?'선택한 위치를 카페로 등록합니다.':'선택한 위치를 식당으로 등록합니다.')}
function setRoutePoint(kind){const point={...clickedMapPoint};if(kind==='start'){routeStartPoint=point;$('#routeStartLabel').textContent=`출발: ${point.address}`}else{routeEndPoint=point;$('#routeEndLabel').textContent=`도착: ${point.address}`}$('#routePointBar').classList.add('show');$('#mapClickActions').classList.remove('show');toast(kind==='start'?'출발지를 선택했어요.':'도착지를 선택했어요.')}
$$('[data-map-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.mapAction;a==='cafe'||a==='food'?registerFromMap(a):setRoutePoint(a)});
$('#showPointRoute').onclick=()=>{if(!routeStartPoint||!routeEndPoint)return toast('출발지와 도착지를 모두 선택해주세요.');const km=map.distance(routeStartPoint,routeEndPoint)/1000;if(!$('#pointRouteDialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="pointRouteDialog"><div class="form-card"><button class="close" onclick="pointRouteDialog.close()">×</button><p class="eyebrow">ROUTE GUIDE</p><h2>선택 위치 길찾기</h2><div id="pointRouteSummary"></div><div class="route-modes"><button data-point-mode="transit">🚌 대중교통</button><button data-point-mode="walk">🚶 도보</button><button data-point-mode="drive">🚗 자동차</button><button data-point-mode="bike">🚲 자전거</button></div><div id="pointRouteResult"></div></div></dialog>');$('#pointRouteSummary').innerHTML=`<b>${routeStartPoint.address}</b><br>→ ${routeEndPoint.address}`;$$('[data-point-mode]').forEach(b=>b.onclick=()=>{const v=routeEstimate(b.dataset.pointMode,km);$('#pointRouteResult').innerHTML=`<b>${v.label}</b><strong>약 ${v.minutes}분</strong><span>${km.toFixed(1)}km · 예상 비용 ${money(v.cost)}</span><small>경로를 불러오는 중입니다.</small>`});if(!$('#pointRouteDialog').open)$('#pointRouteDialog').show()};
$('#clearPointRoute').onclick=()=>{routeStartPoint=routeEndPoint=null;$('#routeStartLabel').textContent='출발지 미선택';$('#routeEndLabel').textContent='도착지 미선택';$('#routePointBar').classList.remove('show')};

// --- 7차 보강: 지도 가게 상세·빠른 정보 수정 ---
if(!$('#placeQuickEditDialog'))document.body.insertAdjacentHTML('beforeend',`<dialog id="placeQuickEditDialog"><form id="placeQuickEditForm" class="form-card quick-store-editor"><button type="button" class="close" onclick="placeQuickEditDialog.close()">×</button><p class="eyebrow">PLACE INFORMATION</p><h2>가게 정보 등록·수정</h2><input type="hidden" name="id"><div class="form-grid"><label>가게 이름<input name="name" required></label><label>업종<select name="type"><option value="cafe">카페</option><option value="food">식당</option></select></label></div><label>주소<input name="area" required></label><button type="button" id="movePlacePin" class="secondary wide">📍 지도에서 핀 옮기기</button><label>영업시간<input name="hours" placeholder="예: 매일 10:00 - 22:00"></label><label>소개<textarea name="desc" placeholder="가게 정보를 알려주세요"></textarea></label><section class="owner-full-edit"><h3>대표·추가 이미지</h3><label>새 대표 이미지<input name="imageFile" type="file" accept="image/*"></label><label>새 추가 사진 여러 장<input name="galleryFiles" type="file" accept="image/*" multiple></label><div id="quickExistingMedia" class="media-manager"></div><h3>메뉴·가격·재고 안내</h3><div id="quickMenuEditor"></div><button type="button" id="quickAddMenu" class="secondary">＋ 메뉴 추가</button></section><button class="primary">수정 내용 저장</button><p class="form-note">기본 정보는 수정할 수 있고, 대표 이미지·추가 사진·메뉴 관리는 해당 점주와 관리자만 가능합니다.</p></form></dialog><section id="userPlacePinBar"><b>핀을 실제 가게 건물로 끌어주세요</b><button id="saveUserPlacePin">이 위치 저장</button><button id="cancelUserPlacePin">취소</button></section>`);
if(!$('#placeQuickEditForm [name=type] option[value=festival]'))$('#placeQuickEditForm [name=type]').insertAdjacentHTML('beforeend','<option value="festival">지역축제</option>');
function quickMenuRow(menu=['','','','']){const status=menu[3]===true?'재고 조금 남음':menu[3]||'';return `<div class="menu-edit-row"><button type="button" class="remove-menu">×</button><label>메뉴 이름<input name="quickMenuName" value="${menu[0]||''}" placeholder="아메리카노"></label><div class="form-grid"><label>가격<input name="quickMenuPrice" value="${menu[1]||''}" placeholder="4,500원 / 변동 가능"></label><label>메뉴 이미지<input name="quickMenuImage" type="file" accept="image/*">${menu[2]?'<small>기존 이미지 등록됨</small>':''}<select name="quickMenuImageAction"><option value="keep">기존 이미지 유지</option><option value="delete">기존 이미지 삭제</option></select></label></div><label>재고 안내<select name="quickMenuStock"><option value="">표시 없음</option><option ${status==='재고 조금 남음'?'selected':''}>재고 조금 남음</option><option ${status==='오늘 소진 예상'?'selected':''}>오늘 소진 예상</option><option ${status==='소진'?'selected':''}>소진</option><option ${status==='판매 일시중지'?'selected':''}>판매 일시중지</option></select></label></div>`}
function openPlaceQuickEdit(id){if(!session)return toast('로그인 후 가게 정보를 수정할 수 있어요.');const p=places.find(x=>x.id===id),f=$('#placeQuickEditForm');if(!p)return;['id','name','type','area','hours','desc'].forEach(k=>f.elements[k].value=p[k]||'');const manager=session.role==='admin'||p.ownerId===session.id;f.querySelector('.owner-full-edit').hidden=!manager;$('#quickMenuEditor').innerHTML=(p.menus?.length?p.menus:[['','','','']]).map(quickMenuRow).join('');$('#quickExistingMedia').innerHTML=[p.image?`<span><img src="${p.image}" alt="대표 이미지"><button type="button" onclick="deleteQuickMedia('image')">대표 삭제</button></span>`:'',...(p.ownerGallery||p.gallery||[]).map((x,i)=>`<span><img src="${x}" alt="추가 사진 ${i+1}"><button type="button" onclick="deleteQuickMedia('gallery',${i})">× 삭제</button></span>`)].join('');$('#detailDialog').close();$('#placeQuickEditDialog').showModal()}
$('#quickAddMenu').onclick=()=>$('#quickMenuEditor').insertAdjacentHTML('beforeend',quickMenuRow());$('#quickMenuEditor').onclick=e=>{if(e.target.classList.contains('remove-menu'))e.target.closest('.menu-edit-row').remove()};
async function deleteQuickMedia(kind,index){const id=$('#placeQuickEditForm').elements.id.value,p=places.find(x=>x.id===id);if(!p||(session.role!=='admin'&&p.ownerId!==session.id))return;if(kind==='image')p.image='';else{p.ownerGallery=p.ownerGallery||p.gallery||[];p.ownerGallery.splice(index,1)}store.set('places',places);try{await syncStoreToServer(p);openPlaceQuickEdit(id);toast('선택한 이미지를 삭제했어요.')}catch(error){toast(error.message)}}window.deleteQuickMedia=deleteQuickMedia;
$('#placeQuickEditForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd),p=places.find(x=>x.id===f.id);if(!p)return;const button=e.submitter,manager=session.role==='admin'||p.ownerId===session.id;button.disabled=true;try{const addressChanged=f.area.trim()!==(p.area||'').trim(),loc=addressChanged?await resolveAddress(f.area):null;Object.assign(p,{name:f.name.trim(),type:f.type,area:f.area.trim(),hours:f.hours.trim()||'영업시간 정보 없음',desc:f.desc.trim()||'상세 정보 확인 필요'});if(loc?.verified){p.lat=loc.lat;p.lng=loc.lng;p.resolvedAddress=loc.label}if(manager){const imageFile=fd.get('imageFile');if(imageFile?.size)p.image=await resizeImage(imageFile);const added=await resizeMany(fd.getAll('galleryFiles').filter(x=>x.size));p.ownerGallery=[...(p.ownerGallery||p.gallery||[]),...added];const names=fd.getAll('quickMenuName'),prices=fd.getAll('quickMenuPrice'),files=fd.getAll('quickMenuImage'),imageActions=fd.getAll('quickMenuImageAction'),stocks=fd.getAll('quickMenuStock'),menus=[];for(let i=0;i<names.length;i++)if(names[i])menus.push([names[i],prices[i]||'가격 문의',files[i]?.size?await resizeImage(files[i],500,360):imageActions[i]==='delete'?'':p.menus?.[i]?.[2]||'',stocks[i]||'']);p.menus=menus;await syncStoreToServer(p)}store.set('places',places);populatePlaces();render();$('#placeQuickEditDialog').close();map.setView([p.lat,p.lng],17);openDetail(p.id);toast(addressChanged&&!loc?.verified?'기본 정보는 저장했지만 주소 위치는 기존 좌표를 유지했어요.':'가게 정보와 메뉴를 서버에 수정했어요.')}catch(error){toast(error.message||'저장하지 못했어요. 이미지 크기와 입력 내용을 확인해주세요.')}finally{button.disabled=false}};
const detailWithEdit=openDetail;openDetail=function(id){detailWithEdit(id);const actions=$('#detailContent .actions');if(actions&&!$('#detailContent .place-edit-button'))actions.insertAdjacentHTML('beforebegin',`<button class="secondary wide place-edit-button" onclick="openPlaceQuickEdit('${id}')">가게 정보 등록·수정</button>`)};

let userPlacePin=null,userPlacePinTarget=null;
$('#movePlacePin').onclick=()=>{const id=$('#placeQuickEditForm').elements.id.value,p=places.find(x=>x.id===id);if(!p)return;userPlacePinTarget=p.id;$('#placeQuickEditDialog').close();map.setView([p.lat,p.lng],19);if(userPlacePin)userPlacePin.remove();userPlacePin=L.marker([p.lat,p.lng],{draggable:true}).addTo(map);$('#userPlacePinBar').classList.add('show');toast('주황색 핀을 손가락이나 마우스로 실제 건물까지 옮겨주세요.')};
$('#saveUserPlacePin').onclick=()=>{const p=places.find(x=>x.id===userPlacePinTarget);if(!p||!userPlacePin)return;const v=userPlacePin.getLatLng();p.lat=v.lat;p.lng=v.lng;p.positionCorrectedBy=session?.id||'guest';store.set('places',places);userPlacePin.remove();userPlacePin=null;$('#userPlacePinBar').classList.remove('show');render();map.setView([p.lat,p.lng],19);openDetail(p.id);toast('옮긴 위치를 바로 저장했어요.')};
$('#cancelUserPlacePin').onclick=()=>{if(userPlacePin)userPlacePin.remove();userPlacePin=null;$('#userPlacePinBar').classList.remove('show');if(userPlacePinTarget)openDetail(userPlacePinTarget)};

async function showDrivingRoute(){if(!routeStartPoint||!routeEndPoint)return toast('출발지와 도착지를 먼저 선택해주세요.');const box=$('#pointRouteResult');box.innerHTML='<b>자동차 실제 경로를 찾는 중…</b>';try{const q=new URLSearchParams({start:`${routeStartPoint.lng},${routeStartPoint.lat}`,goal:`${routeEndPoint.lng},${routeEndPoint.lat}`}),res=await fetch(`/api/directions?${q}`),data=await res.json();if(!res.ok)throw new Error(data.message||'경로 조회 실패');map.drawRoute(data.path,{color:'#ed744f',weight:8});box.innerHTML=`<b>🚗 실시간 자동차 경로</b><strong>약 ${Math.round(data.duration/60000)}분</strong><span>${(data.distance/1000).toFixed(1)}km · 통행료 ${money(data.tollFare)} · 유류비 ${money(data.fuelPrice)}</span><small>네이버 실시간 교통정보를 반영한 도로 경로입니다. 창을 닫으면 지도에서 경로를 볼 수 있어요.</small>`;toast('지도에 주황색 실제 경로를 표시했어요.')}catch(err){box.innerHTML=`<b>자동차 경로 서버 연결 필요</b><small>${err.message}</small>`}}
async function showTransitRoute(){if(!routeStartPoint||!routeEndPoint)return toast('출발지와 도착지를 먼저 선택해주세요.');const box=$('#pointRouteResult');box.innerHTML='<b>대중교통 노선을 찾는 중…</b>';try{const q=new URLSearchParams({start:`${routeStartPoint.lng},${routeStartPoint.lat}`,goal:`${routeEndPoint.lng},${routeEndPoint.lat}`,startName:routeStartPoint.address,endName:routeEndPoint.address}),res=await fetch(`/api/transit?${q}`),data=await res.json();if(!res.ok)throw new Error(data.message||'대중교통 경로 조회 실패');map.drawRoute(data.path,{color:'#6750c9',weight:8});box.innerHTML=`<b>🚌 추천 대중교통 경로</b><strong>약 ${Math.round(data.totalTime/60)}분</strong><span>${(data.totalDistance/1000).toFixed(1)}km · 환승 ${data.transfers}회 · ${money(data.fare)}</span><div class="transit-steps">${data.steps.map(s=>`<p><b>${s.vehicles.length?s.vehicles.join(' · '):s.type==='WALKING'?'도보':'이동'}</b><small>${s.guidance}</small></p>`).join('')}</div>${data.landingURL?`<a class="route-link" target="_blank" href="${data.landingURL}">카카오맵에서 자세히 보기</a>`:''}<small>창을 닫으면 지도에서 보라색 노선을 볼 수 있어요.</small>`;toast('지도에 보라색 대중교통 노선을 표시했어요.')}catch(err){box.innerHTML=`<b>대중교통 경로를 찾지 못했어요.</b><small>${err.message}</small>`}}
async function showActiveRoute(mode){if(!routeStartPoint||!routeEndPoint)return toast('출발지와 도착지를 먼저 선택해주세요.');const walking=mode==='walk',box=$('#pointRouteResult');box.innerHTML=`<b>${walking?'도보':'자전거'} 최적 경로를 찾는 중…</b>`;try{const q=new URLSearchParams({mode,start:`${routeStartPoint.lng},${routeStartPoint.lat}`,goal:`${routeEndPoint.lng},${routeEndPoint.lat}`,startName:routeStartPoint.address,endName:routeEndPoint.address}),res=await fetch(`/api/active-route?${q}`),data=await res.json();if(!res.ok)throw new Error(data.message||'경로 조회 실패');const color=walking?'#29a36a':'#3186d4';map.drawRoute(data.path,{color,weight:8});box.innerHTML=`<b>${walking?'🚶 최단 도보 경로':'🚲 자전거도로 우선 경로'}</b><strong>약 ${Math.round(data.totalTime/60)}분</strong><span>${(data.totalDistance/1000).toFixed(1)}km</span><div class="transit-steps">${data.steps.slice(0,8).map(s=>`<p><small>${s.guidance}</small></p>`).join('')}</div>${data.landingUrl?`<a class="route-link" target="_blank" href="${data.landingUrl}">카카오맵에서 자세히 보기</a>`:''}`;toast(`지도에 ${walking?'초록색 도보':'파란색 자전거'} 경로를 표시했어요.`)}catch(err){box.innerHTML=`<b>${walking?'도보':'자전거'} 경로를 찾지 못했어요.</b><small>${err.message}</small>`}}
const previousShowPointRoute=$('#showPointRoute').onclick;$('#showPointRoute').onclick=()=>{previousShowPointRoute();setTimeout(()=>{const modes={drive:showDrivingRoute,transit:showTransitRoute,walk:()=>showActiveRoute('walk'),bike:()=>showActiveRoute('bike')};Object.entries(modes).forEach(([mode,fn])=>{const b=$(`#pointRouteDialog [data-point-mode=${mode}]`);if(b)b.onclick=fn})},0)};
const routePointSetter=setRoutePoint;setRoutePoint=function(kind){routePointSetter(kind);if(routeStartPoint&&routeEndPoint)setTimeout(()=>{$('#showPointRoute').click();setTimeout(()=>$('#pointRouteDialog [data-point-mode=drive]')?.click(),80)},0)};
const previousClearPointRoute=$('#clearPointRoute').onclick;$('#clearPointRoute').onclick=()=>{previousClearPointRoute();map.clearRoute?.()};

function focusGpsFirst(){if(!navigator.geolocation)return;navigator.geolocation.getCurrentPosition(pos=>{map.setView([pos.coords.latitude,pos.coords.longitude],16);toast('현재 위치를 중심으로 지도를 열었어요.')},()=>{if(session)focusForAccount(session)},{enableHighAccuracy:true,timeout:7000,maximumAge:120000})}
const gpsSetSession=setSession;setSession=function(account,remember=true){gpsSetSession(account,remember);setTimeout(focusGpsFirst,350)};
if(session)setTimeout(focusGpsFirst,500);

function setPlaceRoutePoint(id,kind){const p=places.find(x=>x.id===id);if(!p)return;clickedMapPoint={lat:p.lat,lng:p.lng,address:`${p.name} · ${p.area}`};setRoutePoint(kind);$('#detailDialog').close()}
const detailRouteUnified=openDetail;openDetail=function(id){detailRouteUnified(id);const actions=$('#detailContent .route-actions');if(actions)actions.innerHTML=`<button onclick="setPlaceRoutePoint('${id}','start')">● 출발지로 지정</button><button onclick="setPlaceRoutePoint('${id}','end')">◆ 도착지로 지정</button>`};

// --- 8차 보강: 지역 행사·활동·광고·동네 모임 ---
function festivalIsVisible(p){const now=new Date(),start=new Date(`${p.startDate}T00:00:00`),end=new Date(`${p.endDate}T23:59:59`);start.setDate(start.getDate()-15);return now>=start&&now<=end}
const baseFilteredV8=filtered;filtered=function(){return baseFilteredV8().filter(p=>!p.festival||festivalIsVisible(p))};
const baseColorV8=color;color=function(p){return p.festival?'#d89b18':p.activeSport?'#8b56b3':baseColorV8(p)};
const baseMarkerIconV8=markerIcon;markerIcon=function(p){if(!p.festival&&!p.activeSport)return baseMarkerIconV8(p);return L.divIcon({className:'',html:`<div class="custom-marker ${p.festival?'festival-marker':'sport-marker'}" style="background:${color(p)}"><span>${p.festival?'★':'⚡'}</span></div>`,iconSize:[39,39],iconAnchor:[19,38]})};
featureLabels.activeSport='활기찬 운동';
const sortedFeaturesBeforeActivity=sortedFeatures;sortedFeatures=function(p){return sortedFeaturesBeforeActivity(p).filter(([key])=>key!=='activeSport'||p.type==='activity'||p.activeSport)};

async function loadActiveSports(){const button=$('[data-filter=activeSport]'),center=map.getCenter();button.disabled=true;button.textContent='⚡ 찾는 중…';try{const q=new URLSearchParams({x:center.lng,y:center.lat}),res=await fetch(`/api/sports-search?${q}`),data=await res.json();if(!res.ok)throw new Error(data.message||'검색 실패');let added=0;for(const x of data.places){const id=`kakao-sport-${x.id}`,old=places.find(p=>p.id===id);if(old){old.activeSport=true;continue}places.push({id,name:x.place_name,type:'activity',activeSport:true,area:x.road_address_name||x.address_name,lat:+x.y,lng:+x.x,image:'',ownerGallery:[],visitorGallery:[],desc:`${x.matchedKeyword} · ${x.category_name||'운동 업체'}`,hours:'운영시간 확인 필요',phone:x.phone||'',menus:[],reviews:[],quietTimes:[],featureVotes:{activeSport:1},featureVoters:{activeSport:['kakao-search']},sportTags:[x.matchedKeyword],reservable:false,source:'Kakao Local',externalUrl:x.place_url});added++}store.set('places',places);populatePlaces();render();toast(`현재 지도 주변 운동 업체 ${data.places.length}곳을 찾았어요.`)}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='⚡ 활기찬 운동'}}
$('[data-filter=activeSport]').onclick=()=>{$$('.filter').forEach(b=>b.classList.remove('active'));$('[data-filter=activeSport]').classList.add('active');activeFilter='activeSport';loadActiveSports()};
$('#openNotice').onclick=e=>{e.preventDefault();e.stopPropagation();$('#noticeDialog').showModal()};

const detailActivityV8=openDetail;openDetail=function(id){detailActivityV8(id);const p=places.find(x=>x.id===id),body=$('#detailContent .detail-body');if(!p||!body)return;if(p.activeSport&&p.sportTags?.length)body.querySelector('.review-cloud')?.insertAdjacentHTML('afterbegin',p.sportTags.map(x=>`<i># ${x}</i>`).join(''));if(p.externalUrl)body.querySelector('.actions')?.insertAdjacentHTML('beforebegin',`<a class="secondary wide external-place" target="_blank" rel="noopener" href="${p.externalUrl}">카카오맵 장소 정보 보기</a>`);if(p.festival)body.insertAdjacentHTML('afterbegin',`<section class="festival-info"><b>★ ${p.startDate} ~ ${p.endDate}</b><p>${p.desc||p.eventContent}</p><small>행사 시작 15일 전부터 종료일까지 지도에 표시됩니다.</small></section>`)};

let communities=store.get('communities',[]);
function renderCommunities(){const box=$('#communityList');box.innerHTML=communities.length?communities.map(c=>`<article class="community-item">${c.photo?`<img src="${c.photo}" alt="${c.name}">`:''}<div><small>${c.always?'상시 모집':`${c.start||'미정'} ~ ${c.end||'미정'}`}</small><h3>${c.name}</h3><p>${c.description}</p><b>${c.members?.length||0}/${c.headcount}명 · ${c.price||'무료'}</b><details><summary>주의사항</summary><p>${c.cautions||'등록된 주의사항 없음'}</p></details><button class="secondary" onclick="joinCommunity('${c.id}')">참여하기</button> <button class="secondary" onclick="openCommunityRoom('${c.id}')">대화방</button></div></article>`).join(''):'<p class="form-note">아직 등록된 모임이 없어요.</p>'}
$('#openCommunity').onclick=()=>{renderCommunities();$('#communityDialog').showModal()};
$('#communityForm').onsubmit=async e=>{e.preventDefault();if(!session)return toast('로그인 후 모임을 만들 수 있어요.');const fd=new FormData(e.target),f=Object.fromEntries(fd),photo=fd.get('photo')?.size?await resizeImage(fd.get('photo'),900,600):'';communities.unshift({...f,id:crypto.randomUUID(),photo,always:!!f.always,ownerId:session.id,members:[session.id],memberNames:{[session.id]:session.name},messages:[],votes:[]});store.set('communities',communities);e.target.reset();renderCommunities();toast('동네 모임을 등록했어요.')};
function joinCommunity(id){if(!session)return toast('로그인 후 참여할 수 있어요.');const c=communities.find(x=>x.id===id);c.memberNames=c.memberNames||{};c.memberNames[session.id]=session.name;if(!c.members.includes(session.id)&&c.members.length<+c.headcount)c.members.push(session.id);store.set('communities',communities);renderCommunities();toast('모임 참여가 반영됐어요.')}window.joinCommunity=joinCommunity;
function communityMemberName(c,id){return c.memberNames?.[id]||accounts.find(a=>a.id===id)?.name||(id===session?.id?session.name:'참여자')}
async function hydrateCommunityNames(c){const missing=(c.members||[]).filter(id=>!c.memberNames?.[id]);if(!missing.length)return;try{const response=await fetch('/api/member-names',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:missing})}),data=await response.json();if(!response.ok)throw new Error(data.message);if(!Object.keys(data.names||{}).length)return;c.memberNames={...(c.memberNames||{}),...data.names};store.set('communities',communities);if($('#communityRoomDialog').open&&$('#communityMessageForm').elements.communityId.value===c.id)openCommunityRoom(c.id)}catch(error){console.warn('참여자 이름 조회 실패',error.message)}}
function openCommunityRoom(id){const c=communities.find(x=>x.id===id);if(!session||(!c?.members.includes(session.id)&&session.role!=='admin'))return toast('모임 참여자만 대화방을 볼 수 있어요.');$('#communityRoomTitle').textContent=c.name;$('#communityMessageForm').elements.communityId.value=id;$('#communityMessages').innerHTML=(c.messages||[]).map(m=>`<p><b class="message-name">${m.userId===session.id?'나':m.userName||communityMemberName(c,m.userId)}</b> ${m.text}<small>${new Date(m.at).toLocaleString()}</small></p>`).join('')||'<small>첫 메시지를 남겨보세요.</small>';$('#communityDialog').close();$('#communityRoomDialog').showModal()}
$('#communityMessageForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),c=communities.find(x=>x.id===f.communityId);c.messages=c.messages||[];c.memberNames=c.memberNames||{};c.memberNames[session.id]=session.name;c.messages.push({userId:session.id,userName:session.name,text:f.message,at:new Date().toISOString()});store.set('communities',communities);e.target.elements.message.value='';openCommunityRoom(c.id)};
window.openCommunityRoom=openCommunityRoom;

const ad=store.get('promoBanner',null);if(ad?.image&&ad?.url){$('#promoBanner img').src=ad.image;$('#promoBanner').href=ad.url;$('#promoBanner').hidden=false}

// --- 실제 계정 전환: Better Auth + MongoDB ---
async function authRequest(path,options={}){let response;for(let attempt=0;attempt<2;attempt++){try{response=await fetch(`/api/auth/${path}`,{credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});break}catch(cause){if(attempt===0){await new Promise(resolve=>setTimeout(resolve,700));continue}const error=new Error('인증 서버에 연결하지 못했습니다. 인터넷 연결을 확인한 뒤 다시 시도해주세요.');error.isNetworkError=true;error.cause=cause;throw error}}let data=null;try{data=await response.json()}catch{}if(!response.ok)throw new Error(data?.message||data?.error?.message||'계정 요청을 처리하지 못했어요.');return data}
function applyServerSession(data){const user=data?.user;if(!user)return false;session={id:user.id,name:user.name,email:user.email,role:user.userType||'user',homeLocation:user.homeLocation||''};localStorage.removeItem('masil_session');sessionStorage.removeItem('masil_session');$('#authGate').classList.add('hidden');$('#openOwner').textContent=session.name?.slice(0,2)||'MY';$('#ownerTitle').textContent=session.role==='owner'?'점주 센터':'마이 마실';render();setTimeout(()=>focusForAccount(session),150);return true}
async function restoreServerSession(){try{const data=await authRequest('get-session',{method:'GET'});if(!applyServerSession(data)){session=null;localStorage.removeItem('masil_session');sessionStorage.removeItem('masil_session');$('#authGate').classList.remove('hidden')}}catch{session=null;$('#authGate').classList.remove('hidden')}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),email=String(f.email||'').trim().toLowerCase(),button=e.submitter||e.target.querySelector('button[type="submit"]'),feedback=$('#loginFeedback');feedback.textContent='';feedback.classList.remove('show');if(button)button.disabled=true;try{try{await authRequest('sign-in/email',{method:'POST',body:JSON.stringify({email,password:f.password,rememberMe:!!f.remember})})}catch(serverError){if(serverError.isNetworkError)throw serverError;const legacyHash=await hash(f.password),legacy=accounts.find(x=>String(x.email||'').toLowerCase()===email&&x.passwordHash===legacyHash&&x.role===f.role);if(!legacy){const message=/invalid email|invalid password|credential/i.test(serverError.message||'')?'가입 이메일 또는 비밀번호가 맞지 않습니다.':serverError.message||'로그인하지 못했습니다.';throw new Error(message)}await authRequest('sign-up/email',{method:'POST',body:JSON.stringify({name:legacy.name||email.split('@')[0],email:legacy.email,password:f.password,userType:legacy.role||f.role,homeLocation:legacy.homeLocation||''})});toast('기존 계정을 새 서버 계정으로 안전하게 전환했어요.')}const current=await authRequest('get-session',{method:'GET'}),actualRole=current?.user?.role==='admin'?'admin':current?.user?.userType||'user';if(actualRole!==f.role){await authRequest('sign-out',{method:'POST',body:'{}'}).catch(()=>{});const labels={user:'일반 이용자',owner:'점주',admin:'관리자'};throw new Error(`이 계정은 ${labels[actualRole]} 계정입니다. ${labels[actualRole]}로 선택해 로그인해주세요.`)}if(!applyServerSession(current))throw new Error('로그인 세션을 확인하지 못했어요.');toast(`${current.user.name}님, 반가워요!`)}catch(error){const message=error.message||'로그인 중 문제가 생겼습니다. 잠시 후 다시 시도해주세요.';feedback.textContent=message;feedback.classList.add('show');toast(message)}finally{if(button)button.disabled=false}};
$('#signupForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd),button=e.submitter;button.disabled=true;try{const homeLocation=f.role==='owner'?f.storeAddress:f.homeLocation;await authRequest('sign-up/email',{method:'POST',body:JSON.stringify({name:f.name,email:f.email,password:f.password,userType:f.role,homeLocation})});const current=await authRequest('get-session',{method:'GET'});applyServerSession(current);if(f.role==='owner'&&f.storeName){const loc=await resolveAddress(f.storeAddress),p={id:crypto.randomUUID(),ownerId:current.user.id,name:f.storeName,area:f.storeAddress,type:'cafe',lat:loc.lat,lng:loc.lng,image:await resizeImage(fd.get('storeImage')),hours:'영업시간 등록 필요',menus:f.firstMenu?[[f.firstMenu,f.firstPrice||'가격 문의','']]:[],desc:'점주가 등록한 가게',quietTimes:[],reviews:[],featureVotes:{},featureVoters:{},reservable:true,acceptingReservations:true};places.push(p);store.set('places',places);populatePlaces();render()}$('#signupDialog').close();e.target.reset();toast('MongoDB 계정 가입이 완료됐어요.')}catch(error){toast(error.message)}finally{button.disabled=false}};
async function serverLogout(dialog){try{await authRequest('sign-out',{method:'POST',body:'{}'})}catch{}localStorage.removeItem('masil_session');sessionStorage.removeItem('masil_session');session=null;dialog?.close();$('#authGate').classList.remove('hidden');render()}
$('#logoutBtn').onclick=()=>serverLogout($('#accountDialog'));if($('#ownerLogout'))$('#ownerLogout').onclick=()=>serverLogout($('#ownerDialog'));
$('#deleteAccountBtn').onclick=async()=>{if(!session||!confirm('회원 계정과 로그인 세션을 영구 삭제할까요?'))return;try{await authRequest('delete-user',{method:'POST',body:JSON.stringify({callbackURL:'/'})});await serverLogout($('#accountDialog'));toast('회원 탈퇴가 완료됐어요.')}catch(error){toast(error.message)}};
$('#demoLogin').hidden=true;
restoreServerSession();

// --- 관리자·공용 콘텐츠·교차 필터 ---
const applySessionBeforeAdmin=applyServerSession;applyServerSession=function(data){const ok=applySessionBeforeAdmin(data);if(ok&&data.user.role==='admin'){session.role='admin';$('#openOwner').textContent='관리';$('#ownerTitle').textContent='관리자 센터'}return ok};
$('#signupRole').onchange=e=>{const role=e.target.value,owner=role==='owner',adminRole=role==='admin';$('#ownerSignupFields').hidden=!owner;$('#userSignupFields').hidden=owner||adminRole;$('#adminSignupFields').hidden=!adminRole;$('#signupForm [name=homeLocation]').required=!owner&&!adminRole;$('#signupForm [name=adminCode]').required=adminRole;['storeName','storeAddress'].forEach(n=>$('#signupForm [name='+n+']').required=owner)};
$('#signupForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd),button=e.submitter;button.disabled=true;try{const requestedRole=f.role,userType=requestedRole==='admin'?'user':requestedRole,homeLocation=requestedRole==='owner'?f.storeAddress:(f.homeLocation||'');await authRequest('sign-up/email',{method:'POST',body:JSON.stringify({name:f.name,email:f.email,password:f.password,userType,homeLocation})});if(requestedRole==='admin'){const activated=await fetch('/api/admin-activate',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:f.adminCode})}),activation=await activated.json();if(!activated.ok){try{await authRequest('delete-user',{method:'POST',body:JSON.stringify({password:f.password})})}catch{}throw new Error(activation.message||'관리자 등록 실패')}}const current=await authRequest('get-session',{method:'GET'});applyServerSession(current);if(requestedRole==='owner'&&f.storeName){const loc=await resolveAddress(f.storeAddress);await contentRequest('',{method:'POST',body:JSON.stringify({kind:'store',name:f.storeName,type:'cafe',area:f.storeAddress,lat:loc.lat,lng:loc.lng,desc:'점주가 등록한 가게',ownerId:current.user.id,claimable:false})});await loadServerContent()}$('#signupDialog').close();e.target.reset();toast(requestedRole==='admin'?'첫 관리자 계정을 등록했어요.':'MongoDB 계정 가입이 완료됐어요.')}catch(error){toast(error.message)}finally{button.disabled=false}};

async function contentRequest(path='',options={}){const response=await fetch(`/api/content${path}`,{credentials:'include',headers:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok)throw new Error(data.message||'공용 정보를 처리하지 못했어요.');return data}
async function syncStoreToServer(p){if(!p?.serverContentId)return;if(p.festival||p.type==='festival'){const keys=['name','area','hours','desc','eventContent','startDate','endDate','externalUrl','image'],festival=Object.fromEntries(keys.map(key=>[key,p[key]]).filter(([,value])=>value!==undefined));return contentRequest('',{method:'PATCH',body:JSON.stringify({id:p.serverContentId,action:'updateFestival',festival})})}const keys=['name','type','area','hours','phone','desc','image','menuBoard','ownerGallery','menus','businessStatus','closedDate','parking','publicParking','cozy','quiet','open24','solo','groupFriendly','pet','splitRoom'],storeData=Object.fromEntries(keys.map(key=>[key,p[key]]).filter(([,value])=>value!==undefined));await contentRequest('',{method:'PATCH',body:JSON.stringify({id:p.serverContentId,action:'updateStore',store:storeData})})}
let promoAds=[],promoAdIndex=0,promoAdTimer=null;
function showPromoAd(index=0){const banner=$('#promoBanner');if(!promoAds.length){banner.hidden=true;banner.removeAttribute('href');return}promoAdIndex=index%promoAds.length;const ad=promoAds[promoAdIndex];banner.querySelector('img').src=ad.image;banner.href=ad.url;banner.hidden=false}
function setPromoAds(items){promoAds=items.filter(x=>x.kind==='ad'&&x.image&&x.url);promoAdIndex=0;clearInterval(promoAdTimer);showPromoAd();if(promoAds.length>1)promoAdTimer=setInterval(()=>showPromoAd(promoAdIndex+1),20000)}
async function loadServerContent(){try{const {items}=await contentRequest(),mapItems=items.filter(x=>x.kind==='store'||x.kind==='festival');for(const item of mapItems){const converted={...item,id:item.id,festival:item.kind==='festival',claimable:item.kind==='store'&&!item.ownerId,image:item.image||'',ownerGallery:item.ownerGallery||[],visitorGallery:item.visitorGallery||[],hours:item.hours||'정보 확인 중',menus:item.menus||[],reviews:item.reviews||[],quietTimes:item.quietTimes||[],featureVotes:item.featureVotes||{},featureVoters:item.featureVoters||{},reservable:!!item.ownerId};const i=places.findIndex(p=>p.serverContentId===item.id||p.id===item.id);converted.serverContentId=item.id;if(i>=0)places[i]={...places[i],...converted};else places.push(converted)}setPromoAds(items);populatePlaces();render();renderAdminContent(items)}catch(error){console.warn('공용 콘텐츠 로드 실패',error.message)}}
async function loadTourFestivals(){try{const response=await fetch('/api/festivals'),data=await response.json();if(!response.ok)throw new Error(data.message||'축제 조회 실패');for(const item of data.festivals||[]){const converted={...item,image:item.image||'',ownerGallery:[],visitorGallery:[],hours:`${item.startDate} ~ ${item.endDate}`,menus:[],reviews:[],quietTimes:[],featureVotes:{},featureVoters:{},reservable:false};const i=places.findIndex(p=>p.id===item.id);if(i>=0)places[i]={...places[i],...converted};else places.push(converted)}populatePlaces();render()}catch(error){console.warn('TourAPI 축제 로드 실패',error.message)}}
