const combinableFilters=new Set(['parking','publicParking','cozy','splitRoom','quiet']);let selectedFeatureFilters=new Set(),mapModeFilter='all';filtered=function(){return places.filter(p=>{if(p.festival&&!festivalIsVisible(p))return false;const match=!search||`${p.name} ${p.area} ${p.desc}`.toLowerCase().includes(search);if(!match||![...selectedFeatureFilters].every(k=>p[k]||p.featureVotes?.[k]))return false;if(mapModeFilter==='visited')return visited.has(p.id);if(mapModeFilter==='festival')return !!p.festival;if(mapModeFilter==='activeSport')return !!p.activeSport;return true})};
