$('#saveUserPlacePin').onclick=async()=>{const p=places.find(x=>x.id===userPlacePinTarget);if(!p||!userPlacePin)return;const button=$('#saveUserPlacePin'),v=userPlacePin.getLatLng(),samePlace=x=>x.name.trim()===p.name.trim()&&x.area.replace(/\s/g,'')===p.area.replace(/\s/g,'');button.disabled=true;try{const serverIds=[...new Set(places.filter(samePlace).map(x=>x.serverContentId).filter(Boolean))];for(const id of serverIds)await contentRequest('',{method:'PATCH',body:JSON.stringify({id,action:'updatePosition',lat:v.lat,lng:v.lng})});places.filter(samePlace).forEach(x=>{x.lat=v.lat;x.lng=v.lng;x.positionCorrectedBy=session?.id});store.set('places',places);userPlacePin.remove();userPlacePin=null;$('#userPlacePinBar').classList.remove('show');render();map.setView([v.lat,v.lng],19);openDetail(p.id);toast(serverIds.length?'같은 가게의 중복 핀까지 새 위치로 저장했어요.':'이 브라우저에 핀 위치를 저장했어요.')}catch(error){toast(error.message)}finally{button.disabled=false}};

