async function applyRouteStartSearch(){const input=$('#routeStartSearch'),query=input.value.trim();if(!query)return toast('출발지 주소나 가게 이름을 입력해주세요.');const local=places.find(p=>`${p.name} ${p.area}`.toLowerCase().includes(query.toLowerCase()));const loc=local?{lat:local.lat,lng:local.lng,label:`${local.name} · ${local.area}`,verified:true}:await resolveAddress(query);if(!loc.verified&&!local)return toast('출발지 검색 결과가 불확실해요. 지도에서 직접 선택해주세요.');routeStartPoint={lat:loc.lat,lng:loc.lng,address:loc.label||query};input.value=routeStartPoint.address;$('#routePointBar').classList.add('show');toast('출발지를 선택했어요.');if(routeEndPoint)setTimeout(()=>$('#showPointRoute').click(),0)}
