function ensureCommunityOwnerTools(){if($('#communityOwnerTools'))return;$('#communityRoomDialog .form-card').insertAdjacentHTML('beforeend',`<section id="communityNotices" class="community-notices"></section><section id="communityPolls" class="community-polls"></section><section id="communityOwnerTools" hidden><h3>모임 관리</h3><form id="communityNoticeForm"><input type="hidden" name="communityId"><label>공지 내용<textarea name="notice" required maxlength="500"></textarea></label><button class="secondary wide">공지 올리기</button></form><form id="communityPollCreateForm"><input type="hidden" name="communityId"><label>투표 질문<input name="question" required></label><label>선택 항목<input name="options" required placeholder="예: 토요일, 일요일, 평일 저녁"></label><button class="secondary wide">투표 만들기</button></form><form id="communityKickForm"><input type="hidden" name="communityId"><h4>여러 회원 선택해 내보내기</h4><div id="communityMemberChecks"></div><button class="danger wide">선택 회원 내보내기</button></form></section>`);$('#communityNoticeForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),c=communities.find(x=>x.id===f.communityId);if(!canManageCommunity(c))return;c.notices=c.notices||[];c.notices.unshift({id:crypto.randomUUID(),text:f.notice,at:new Date().toISOString()});store.set('communities',communities);e.target.elements.notice.value='';openCommunityRoom(c.id)};$('#communityPollCreateForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),c=communities.find(x=>x.id===f.communityId);if(!canManageCommunity(c))return;const options=f.options.split(',').map(x=>x.trim()).filter(Boolean);if(options.length<2)return toast('투표 항목을 쉼표로 2개 이상 입력해주세요.');c.ownerPolls=c.ownerPolls||[];c.ownerPolls.unshift({id:crypto.randomUUID(),question:f.question,options,votes:{}});store.set('communities',communities);e.target.reset();openCommunityRoom(c.id)};$('#communityKickForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),c=communities.find(x=>x.id===f.get('communityId'));if(!canManageCommunity(c))return;const selected=f.getAll('member');if(!selected.length)return toast('내보낼 회원을 선택해주세요.');if(!confirm(`${selected.length}명을 모임에서 내보낼까요?`))return;c.members=c.members.filter(id=>!selected.includes(id));store.set('communities',communities);openCommunityRoom(c.id);toast('선택한 회원을 내보냈어요.')}}
