function editCommunityPoll(communityId,pollId){const c=communities.find(x=>x.id===communityId),p=c?.ownerPolls?.find(x=>x.id===pollId);if(!p||!canManageCommunity(c))return;const question=prompt('투표 질문을 수정하세요.',p.question)?.trim();if(!question)return;const optionText=prompt('선택 항목을 쉼표로 구분하세요.',p.options.join(', '));const options=optionText?.split(',').map(x=>x.trim()).filter(Boolean);if(!options||options.length<2)return toast('선택 항목은 2개 이상이어야 해요.');p.question=question;p.options=options;p.votes={};store.set('communities',communities);openCommunityRoom(communityId)}window.editCommunityPoll=editCommunityPoll;
function deleteCommunityPoll(communityId,pollId){const c=communities.find(x=>x.id===communityId);if(!c||!canManageCommunity(c)||!confirm('이 투표를 삭제할까요?'))return;c.ownerPolls=(c.ownerPolls||[]).filter(x=>x.id!==pollId);store.set('communities',communities);openCommunityRoom(communityId)}window.deleteCommunityPoll=deleteCommunityPoll;
const communityRoomBeforeOwner=openCommunityRoom;openCommunityRoom=function(id){communityRoomBeforeOwner(id);const c=communities.find(x=>x.id===id);if(!c||!$('#communityRoomDialog').open)return;hydrateCommunityNames(c);ensureCommunityOwnerTools();const manager=canManageCommunity(c),tools=$('#communityOwnerTools');tools.hidden=!manager;$$('#communityOwnerTools [name=communityId]').forEach(x=>x.value=id);$('#communityMemberChecks').innerHTML=(c.members||[]).filter(x=>x!==c.ownerId).map(x=>`<label class="check"><input type="checkbox" name="member" value="${x}"> ${communityMemberName(c,x)}</label>`).join('')||'<small>내보낼 다른 참여자가 없어요.</small>';$('#communityNotices').innerHTML=`<h3>모임 공지</h3>${(c.notices||[]).map(n=>`<article><div><b>📌 ${n.text}</b>${manager?`<span class="community-manage-actions"><button onclick="editCommunityNotice('${id}','${n.id}')">수정</button><button class="danger" onclick="deleteCommunityNotice('${id}','${n.id}')">삭제</button></span>`:''}</div><small>${new Date(n.at).toLocaleString()}${n.editedAt?' · 수정됨':''}</small></article>`).join('')||'<small>등록된 공지가 없어요.</small>'}`;$('#communityPolls').innerHTML=`<h3>모임 투표</h3>${(c.ownerPolls||[]).map(p=>`<article><div class="poll-head"><b>${p.question}</b>${manager?`<span class="community-manage-actions"><button onclick="editCommunityPoll('${id}','${p.id}')">수정</button><button class="danger" onclick="deleteCommunityPoll('${id}','${p.id}')">삭제</button></span>`:''}</div><div>${p.options.map(o=>{const count=Object.values(p.votes||{}).filter(x=>x===o).length,selected=p.votes?.[session.id]===o;return `<button class="${selected?'active':''}" onclick="voteCommunityPoll('${id}','${p.id}','${o.replaceAll("'","&#39;")}')">${o} · ${count}표</button>`}).join('')}</div><small>선택한 항목을 다시 누르면 내 표가 취소됩니다.</small></article>`).join('')||'<small>진행 중인 투표가 없어요.</small>'}`};window.openCommunityRoom=openCommunityRoom;

document.title='모험지도 — 서울·인천 동네 탐험';$$('h2').forEach(x=>{if(x.textContent.includes('마실지도'))x.textContent=x.textContent.replace('마실지도','모험지도')});

// 사용자가 고르는 편안한 배경 테마
const savedTheme=localStorage.getItem('adventure_theme')||'leaf';document.documentElement.dataset.theme=savedTheme;
function renderThemeChoice(){$$('[data-theme-choice]').forEach(button=>button.classList.toggle('active',button.dataset.themeChoice===(document.documentElement.dataset.theme||'leaf')))}
$('#openTheme').onclick=()=>{renderThemeChoice();$('#themeDialog').showModal()};
$$('[data-theme-choice]').forEach(button=>button.onclick=()=>{const theme=button.dataset.themeChoice;document.documentElement.dataset.theme=theme;localStorage.setItem('adventure_theme',theme);renderThemeChoice();toast('배경 색을 바꿨어요.')});

// 모든 계정의 표시 이름·비밀번호 변경
$('#openAccountSettings').onclick=()=>{if(!session)return $('#authGate').classList.remove('hidden');$('#accountNameForm').elements.name.value=session.name||'';$('#accountSettingsDialog').showModal()};
$('#accountNameForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter,name=e.target.elements.name.value.trim();button.disabled=true;try{await authRequest('update-user',{method:'POST',body:JSON.stringify({name})});session.name=name;$('#openOwner').textContent=session.role==='owner'?'가게 정보수정':name.slice(0,2);communities.forEach(c=>{if(c.members?.includes(session.id)){c.memberNames=c.memberNames||{};c.memberNames[session.id]=name}(c.messages||[]).filter(m=>m.userId===session.id).forEach(m=>m.userName=name)});store.set('communities',communities);toast('표시 이름을 변경했어요.')}catch(error){toast(error.message)}finally{button.disabled=false}};
$('#accountPasswordForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),button=e.submitter;if(f.newPassword!==f.confirmPassword)return toast('새 비밀번호 확인이 일치하지 않습니다.');button.disabled=true;try{await authRequest('change-password',{method:'POST',body:JSON.stringify({currentPassword:f.currentPassword,newPassword:f.newPassword,revokeOtherSessions:true})});e.target.reset();toast('비밀번호를 변경했어요. 다른 기기의 로그인은 해제됩니다.')}catch(error){toast(error.message)}finally{button.disabled=false}};

// 전체 공지: 글과 복수 이미지 등록·수정·삭제
let globalNotices=[];
function renderGlobalNotices(){const dialog=$('#noticeDialog'),admin=session?.role==='admin';dialog.innerHTML=`<div class="form-card"><button type="button" class="close" onclick="noticeDialog.close()">×</button><p class="eyebrow">NOTICE</p><h2>모험지도 소식</h2><div id="globalNoticeList">${globalNotices.map(n=>`<article class="global-notice"><p>${n.text||''}</p>${n.images?.length?`<div class="notice-images">${n.images.map((img,i)=>`<span><img src="${img}" alt="공지 이미지 ${i+1}">${admin?`<button class="danger" onclick="deleteGlobalNoticeImage('${n.id}',${i})">삭제</button>`:''}</span>`).join('')}</div>`:''}${admin?`<div class="notice-actions"><button onclick="editGlobalNotice('${n.id}')">수정</button><button class="danger" onclick="deleteGlobalNotice('${n.id}')">삭제</button></div>`:''}</article>`).join('')||'<p class="form-note">등록된 공지가 없습니다.</p>'}</div>${admin?`<hr><form id="globalNoticeForm"><input type="hidden" name="id"><label>공지 글<textarea name="text" required maxlength="3000"></textarea></label><label>이미지 여러 장<input name="images" type="file" accept="image/*" multiple></label><button class="primary">공지 저장</button><button type="button" class="secondary wide" onclick="resetGlobalNoticeForm()">수정 취소·새 공지</button></form>`:''}</div>`;if(admin)$('#globalNoticeForm').onsubmit=saveGlobalNotice}
async function loadGlobalNotices(){try{const {items}=await contentRequest();globalNotices=items.filter(x=>x.kind==='notice');renderGlobalNotices()}catch(error){toast(error.message)}}
async function saveGlobalNotice(e){e.preventDefault();const fd=new FormData(e.target),id=fd.get('id'),old=globalNotices.find(x=>x.id===id),added=await resizeMany(fd.getAll('images').filter(x=>x.size)),notice={text:fd.get('text').trim(),images:[...(old?.images||[]),...added]};try{if(id)await contentRequest('',{method:'PATCH',body:JSON.stringify({id,action:'updateNotice',notice})});else await contentRequest('',{method:'POST',body:JSON.stringify({kind:'notice',...notice})});await loadGlobalNotices();toast(id?'공지를 수정했어요.':'공지를 등록했어요.')}catch(error){toast(error.message)}}
function editGlobalNotice(id){const n=globalNotices.find(x=>x.id===id),form=$('#globalNoticeForm');if(!n||!form)return;form.elements.id.value=id;form.elements.text.value=n.text||'';form.scrollIntoView({behavior:'smooth',block:'center'})}window.editGlobalNotice=editGlobalNotice;
function resetGlobalNoticeForm(){const form=$('#globalNoticeForm');form?.reset();if(form)form.elements.id.value=''}window.resetGlobalNoticeForm=resetGlobalNoticeForm;
async function deleteGlobalNoticeImage(id,index){const n=globalNotices.find(x=>x.id===id);if(!n)return;n.images.splice(index,1);try{await contentRequest('',{method:'PATCH',body:JSON.stringify({id,action:'updateNotice',notice:{images:n.images}})});await loadGlobalNotices();toast('공지 이미지를 삭제했어요.')}catch(error){toast(error.message)}}window.deleteGlobalNoticeImage=deleteGlobalNoticeImage;
async function deleteGlobalNotice(id){if(!confirm('이 공지를 삭제할까요?'))return;try{await contentRequest(`?id=${encodeURIComponent(id)}`,{method:'DELETE'});await loadGlobalNotices();toast('공지를 삭제했어요.')}catch(error){toast(error.message)}}window.deleteGlobalNotice=deleteGlobalNotice;
$('#openNotice').onclick=e=>{e.preventDefault();e.stopPropagation();loadGlobalNotices();$('#noticeDialog').showModal()};

// 모임 목록은 상세 보기 후 참여·대화방으로 이동
if(!$('#communityPreviewDialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="communityPreviewDialog" class="community-preview"><div id="communityPreviewContent" class="form-card"></div></dialog>');
communityCardMarkup=function(c){return `<article class="community-item">${c.photo?`<img src="${c.photo}" alt="${c.name}">`:''}<div><small>${c.always?'상시 모집':`${c.start||'미정'} ~ ${c.end||'미정'}`}</small><h3>${c.name}</h3><b>${c.members?.length||0}/${c.headcount}명 · ${c.price||'무료'}</b><div><button class="primary compact" onclick="previewCommunity('${c.id}')">살펴보기</button></div></div></article>`};
function previewCommunity(id){const c=communities.find(x=>x.id===id);if(!c)return;$('#communityPreviewContent').innerHTML=`<button class="close" onclick="communityPreviewDialog.close()">×</button>${c.photo?`<img class="community-preview-hero" src="${c.photo}" alt="${c.name}">`:''}<div class="community-preview-body"><p class="eyebrow">COMMUNITY PREVIEW</p><h2>${c.name}</h2><b id="communityPreviewCount">${c.members?.length||0}/${c.headcount}명 · ${c.price||'무료'}</b><p>${c.description}</p>${c.photo?`<div class="community-preview-images"><img src="${c.photo}" alt="모임 소개 이미지"></div>`:''}<details><summary>주의사항</summary><p>${c.cautions||'등록된 주의사항 없음'}</p></details><div class="community-preview-footer"><button class="secondary" onclick="joinCommunity('${id}');previewCommunity('${id}')">참여하기</button><button class="primary" onclick="communityPreviewDialog.close();openCommunityRoom('${id}')">선택·대화방</button></div></div>`;if(!$('#communityPreviewDialog').open)$('#communityPreviewDialog').showModal()}window.previewCommunity=previewCommunity;
const joinCommunityBeforePreview=joinCommunity;joinCommunity=function(id){joinCommunityBeforePreview(id);renderCommunitySide();renderCommunities()};window.joinCommunity=joinCommunity;

// 지도 이동이 끝나면 현재 중심 주변 카페·식당을 자동 탐색
let nearbyMoveTimer=null,lastNearbyGrid='';map.on('moveend',()=>{clearTimeout(nearbyMoveTimer);nearbyMoveTimer=setTimeout(()=>{const c=map.getCenter(),key=`${c.lat.toFixed(2)},${c.lng.toFixed(2)}`;if(map.getZoom()<13||key===lastNearbyGrid||!$('#importOsmPlaces'))return;lastNearbyGrid=key;$('#importOsmPlaces').click()},1100)});

// 학교·공공시설 이름도 카카오 장소검색으로 출발지 지정
applyRouteStartSearch=async function(){const input=$('#routeStartSearch'),query=input.value.trim();if(!query)return toast('출발지 주소나 장소 이름을 입력해주세요.');const local=places.find(p=>`${p.name} ${p.area}`.toLowerCase().includes(query.toLowerCase()));let loc=local?{lat:local.lat,lng:local.lng,label:`${local.name} · ${local.area}`,verified:true}:null;if(!loc)try{const response=await fetch(`/api/place-search?query=${encodeURIComponent(query)}`),data=await response.json(),candidate=data.places?.find(p=>/서울|인천|경기/.test(p.address))||data.places?.[0];if(candidate)loc={lat:candidate.lat,lng:candidate.lng,label:`${candidate.name} · ${candidate.address}`,verified:true}}catch(error){}if(!loc)loc=await resolveAddress(query);if(!loc.verified)return toast('장소를 찾지 못했어요. 학교명 뒤에 지역명도 함께 입력해주세요.');routeStartPoint={lat:loc.lat,lng:loc.lng,address:loc.label||query};input.value=routeStartPoint.address;$('#routePointBar').classList.add('show');toast('출발지를 선택했어요.');if(routeEndPoint)setTimeout(()=>$('#showPointRoute').click(),0)};
